"use client";

import { useState } from "react";
import { useSubmit } from "@/lib/api";
import { TRANSACTION_CATEGORIES, ACCOUNT_TYPES, INSURANCE_TYPES } from "@/components/finance/charts/InvestmentCharts";
import { Card, Skeleton } from "@/components/finance";
import { Button } from "@/components/finance/charts/InvestmentCharts";

interface EntityFormProps {
  type: "account" | "holding" | "debt" | "goal" | "insurance";
  onSaved: () => void;
}

const EntityForms: React.FC<EntityFormProps> = ({ type, onSaved }) => {
  const [formData, setFormData] = useState<{ [key: string]: any }>({});
  const submit = useSubmit();

  const handleSubmit = async () => {
    await submit(`/api/finance/${type}`, "POST", formData);
    onSaved();
  };

  return (
    <Card>
      <form onSubmit={(e) => e.preventDefault()}>
        {type === "account" && (
          <>
            <label htmlFor="accountType">Account Type:</label>
            <select
              id="accountType"
              value={formData.accountType}
              onChange={(e) => setFormData({ ...formData, accountType: e.target.value })}
            >
              {ACCOUNT_TYPES.map((type) => (
                <option key={type} value={type}>
                  {type}
                </option>
              ))}
            </select>
            <label htmlFor="name">Name:</label>
            <input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />
          </>
        )}
        {type === "holding" && (
          <>
            <label htmlFor="type">Type:</label>
            <select
              id="type"
              value={formData.type}
              onChange={(e) => setFormData({ ...formData, type: e.target.value })}
            >
              {TRANSACTION_CATEGORIES.map((category) => (
                <option key={category} value={category}>
                  {category}
                </option>
              ))}
            </select>
            <label htmlFor="name">Name:</label>
            <input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />
            <label htmlFor="price">Price:</label>
            <input
              id="price"
              type="number"
              value={formData.price}
              onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) })}
            />
          </>
        )}
        {type === "debt" && (
          <>
            <label htmlFor="name">Name:</label>
            <input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />
            <label htmlFor="interestRate">Interest Rate:</label>
            <input
              id="interestRate"
              type="number"
              value={formData.interestRate}
              onChange={(e) => setFormData({ ...formData, interestRate: parseFloat(e.target.value) })}
            />
          </>
        )}
        {type === "goal" && (
          <>
            <label htmlFor="name">Name:</label>
            <input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />
            <label htmlFor="start_date">Start Date:</label>
            <input
              id="start_date"
              type="date"
              value={formData.start_date}
              onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
            />
            <label htmlFor="current_amount">Current Amount:</label>
            <input
              id="current_amount"
              type="number"
              value={formData.current_amount}
              onChange={(e) => setFormData({ ...formData, current_amount: parseFloat(e.target.value) })}
            />
          </>
        )}
        {type === "insurance" && (
          <>
            <label htmlFor="name">Name:</label>
            <input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            />
            <label htmlFor="type">Type:</label>
            <select
              id="type"
              value={formData.type}
              onChange={(e) => setFormData({ ...formData, type: e.target.value })}
            >
              {INSURANCE_TYPES.map((type) => (
                <option key={type} value={type}>
                  {type}
                </option>
              ))}
            </select>
          </>
        )}
        <Button type="submit" onClick={handleSubmit}>
          Save
        </Button>
      </form>
    </Card>
  );
};

export default EntityForms;
